import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from elasticsearch import Elasticsearch


class ElasticCloudLogQuery:
    def __init__(
        self,
        cloud_id: Optional[str] = None,
        username: Optional[str] = None,
        password: Optional[str] = None,
        api_key: Optional[str] = None,
        index: str = "logs-*",
    ) -> None:
        self.index = index
        cloud_id = cloud_id or os.environ.get("ELASTIC_CLOUD_ID")
        api_key = api_key or os.environ.get("ELASTIC_API_KEY")
        username = username or os.environ.get("ELASTIC_USERNAME")
        password = password or os.environ.get("ELASTIC_PASSWORD")

        if not cloud_id:
            raise ValueError("Missing Elastic Cloud ID. Set ELASTIC_CLOUD_ID or pass cloud_id.")

        if api_key:
            self.client = Elasticsearch(cloud_id=cloud_id, api_key=api_key)
        elif username and password:
            self.client = Elasticsearch(cloud_id=cloud_id, basic_auth=(username, password))
        else:
            raise ValueError(
                "Provide ELASTIC_API_KEY or ELASTIC_USERNAME/ELASTIC_PASSWORD for Elastic Cloud."
            )

    @staticmethod
    def _to_iso8601(value: Optional[datetime]) -> Optional[str]:
        if value is None:
            return None
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc).isoformat()

    def query_recent_logs(
        self,
        field_filters: Dict[str, Any],
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None,
        minutes_back: int = 15,
        size: int = 100,
        time_field: str = "@timestamp",
        sort_desc: bool = True,
    ) -> List[Dict[str, Any]]:
        if end_time is None:
            end_time = datetime.now(timezone.utc)
        if start_time is None:
            start_time = end_time - timedelta(minutes=minutes_back)

        must_filters: List[Dict[str, Any]] = [
            {
                "range": {
                    time_field: {
                        "gte": self._to_iso8601(start_time),
                        "lte": self._to_iso8601(end_time),
                    }
                }
            }
        ]

        for field, value in field_filters.items():
            if isinstance(value, (list, tuple, set)):
                must_filters.append({"terms": {field: list(value)}})
            else:
                must_filters.append({"term": {field: value}})

        body = {
            "size": size,
            "sort": [{time_field: {"order": "desc" if sort_desc else "asc"}}],
            "query": {
                "bool": {
                    "filter": must_filters
                }
            },
        }

        response = self.client.search(index=self.index, body=body)
        hits = response.get("hits", {}).get("hits", [])

        results: List[Dict[str, Any]] = []
        for hit in hits:
            source = hit.get("_source", {})
            results.append(
                {
                    "_index": hit.get("_index"),
                    "_id": hit.get("_id"),
                    "_score": hit.get("_score"),
                    **source,
                }
            )
        return results


def retrieve_recent_log_results(
    field_filters: Dict[str, Any],
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    minutes_back: int = 15,
    size: int = 100,
    index: str = "logs-*",
    time_field: str = "@timestamp",
) -> List[Dict[str, Any]]:
    query_service = ElasticCloudLogQuery(index=index)
    return query_service.query_recent_logs(
        field_filters=field_filters,
        start_time=start_time,
        end_time=end_time,
        minutes_back=minutes_back,
        size=size,
        time_field=time_field,
    )
